SELECT CASE WHEN shipping_fee >= 35 THEN 'LARGE' ELSE 'SMALL' END AS shipping_fee_tier, COUNT(*) AS num_rows, COUNT(*) AS event_count, COUNT(*) FILTER (WHERE status = 'PENDING') AS pending_rows, APPROX_PERCENTILE(shipping_fee, ARRAY(0.25, 0.5, 0.75)) AS shipping_fee_quartiles FROM orders GROUP BY CASE WHEN shipping_fee >= 35 THEN 'LARGE' ELSE 'SMALL' END ORDER BY shipping_fee_tier DESC NULLS LAST;
